<script setup>import{onMounted,reactive,ref}from'vue';import{showSuccessToast}from'vant';import{api}from'../api/crm';const items=ref([]),customers=ref([]),show=ref(false),form=reactive({customerId:'',method:'WECHAT',content:'',nextAction:'',nextFollowUpDate:''});const methods={PHONE:'电话',WECHAT:'微信',VISIT:'拜访',EMAIL:'邮件',OTHER:'其他'};async function load(){[items.value,customers.value]=await Promise.all([api.recentFollowUps(),api.customers('')])}async function add(){await api.createFollowUp({...form,customerId:Number(form.customerId),nextFollowUpDate:form.nextFollowUpDate||null});show.value=false;form.content='';form.nextAction='';showSuccessToast('跟进已记录');load()}onMounted(load)</script>
<template><div class="page safe-top"><van-nav-bar title="跟进记录" left-arrow @click-left="$router.back()" right-text="写跟进" @click-right="show=true"/><section v-for="item in items" :key="item.id" class="card follow"><div class="head"><div><b>{{item.customerName}}</b><span class="tag">{{methods[item.method]}}</span></div><span class="muted">{{item.followUpAt?.slice(0,10)}}</span></div><p>{{item.content}}</p><div v-if="item.nextAction" class="next">下一步：{{item.nextAction}}</div><div class="muted owner">{{item.creatorName}} · 下次跟进 {{item.nextFollowUpDate||'未安排'}}</div></section><div v-if="!items.length" class="empty">暂无跟进记录</div><van-popup v-model:show="show" position="bottom" round><div class="form"><h2>记录客户跟进</h2><label class="select-row"><span>客户</span><select v-model="form.customerId"><option value="" disabled>请选择客户</option><option v-for="c in customers" :key="c.id" :value="c.id">{{c.shortName||c.name}}</option></select></label><div class="inline-label">跟进方式</div><van-radio-group v-model="form.method" direction="horizontal"><van-radio name="PHONE">电话</van-radio><van-radio name="WECHAT">微信</van-radio><van-radio name="VISIT">拜访</van-radio><van-radio name="EMAIL">邮件</van-radio></van-radio-group><van-field v-model="form.content" label="跟进内容" type="textarea" rows="3" required/><van-field v-model="form.nextAction" label="下一步计划" type="textarea" rows="2"/><van-field v-model="form.nextFollowUpDate" label="下次跟进" type="date"/><button class="action-btn" :disabled="!form.customerId||!form.content" @click="add">保存跟进</button></div></van-popup></div></template>
<style scoped>.van-nav-bar{background:transparent;margin:-8px -16px 14px}.head{display:flex;justify-content:space-between}.head .tag{margin-left:8px}.follow p{color:#46566e;line-height:1.65}.next{background:#f1f4f9;border-radius:9px;padding:9px;font-size:12px;color:#65758b}.owner{margin-top:12px}.form{padding:18px 20px 32px}.form h2{margin:0 0 14px}.select-row{display:flex;align-items:center;padding:12px 16px;border-bottom:1px solid #eee;font-size:14px}.select-row span{width:90px;color:#646b75}.select-row select{flex:1;border:0;background:white;font-size:14px;color:#333}.inline-label{font-size:14px;color:#646b75;padding:14px 16px 9px}.van-radio-group{padding:0 16px 14px;gap:13px}.action-btn{margin-top:13px}</style>
